import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, ScrollView, Pressable, KeyboardAvoidingView, Keyboard, Platform, TouchableOpacity } from 'react-native';
import { useRouter } from 'expo-router';
import { useForm, Controller } from 'react-hook-form';
import { AppButton } from '@/components/AppButton';
import { AppInput } from '@/components/AppInput';
import { AppText } from '@/components/AppText';
import { Colors, Spacing, Radius } from '@/constants/theme';
import { User, ArrowLeft, Square, Check, ChevronRight, CircleCheck } from 'lucide-react-native';

export default function RegisterScreen() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [emailVerified, setEmailVerified] = useState(false);
  const [keyboardUp, setKeyboardUp] = useState(false);

  useEffect(() => {
    const showSub = Keyboard.addListener('keyboardDidShow', () => setKeyboardUp(true));
    const hideSub = Keyboard.addListener('keyboardDidHide', () => setKeyboardUp(false));
    return () => {
      showSub.remove();
      hideSub.remove();
    };
  }, []);

  const { control, handleSubmit, watch, formState: { errors } } = useForm({
    defaultValues: {
      name: '',
      mobile: '',
      email: '',
      password: '',
      confirmPassword: '',
    }
  });

  const password = watch('password');

  const onSubmit = (data: { name: string; mobile: string; email: string; password: string; confirmPassword: string }) => {
    if (!emailVerified) {
      alert("Please verify your email address.");
      return;
    }
    if (!acceptedTerms) {
      alert("Please accept the terms and conditions.");
      return;
    }
    
    setLoading(true);
    // Simulate API call and redirect to OTP
    setTimeout(() => {
      setLoading(false);
      router.push({ pathname: '/(auth)/otp', params: { phone: data.mobile } });
    }, 1500);
  };

  const step = 1;

  const renderProgressBar = () => (
    <View style={styles.progressContainer}>
      {[1, 2].map((item, index) => (
        <View key={item} style={styles.progressStep}>
          <View style={[styles.progressDot, step >= item ? styles.progressDotActive : null]}>
            {step > item ? (
              <CircleCheck size={16} color={Colors.white} />
            ) : (
              <AppText variant="caption" weight="bold" color={step === item ? Colors.white : Colors.textTertiary}>
                {item}
              </AppText>
            )}
          </View>
          {index < 1 && <View style={[styles.progressLine, step > item ? styles.progressLineActive : null]} />}
        </View>
      ))}
    </View>
  );

  const renderStepLabels = () => {
    const stepLabels = ['Account', 'Verification'];
    return (
      <View style={styles.stepLabelsContainer}>
        {stepLabels.map((label, index) => {
          const stepNum = index + 1;
          const isActive = step >= stepNum;
          return (
            <AppText key={label} variant="caption" weight={isActive ? 'bold' : 'regular'} color={isActive ? Colors.primary : Colors.textTertiary} style={{ textAlign: 'center', width: 80 }}>
              {label}
            </AppText>
          );
        })}
      </View>
    );
  };

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <View style={styles.header}>
        <Pressable onPress={() => router.back()} hitSlop={12} style={styles.backButton}>
          <ArrowLeft size={24} color={Colors.textPrimary} />
        </Pressable>
        <AppText variant="h4" weight="bold">Register as User</AppText>
        <View style={{ width: 24 }} />
      </View>

      {renderProgressBar()}
      {renderStepLabels()}

      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
        keyboardShouldPersistTaps="handled"
        onScrollBeginDrag={() => Keyboard.dismiss()}
      >
        <View style={styles.formSection}>
          <View style={styles.sectionHeader}>
            <User size={28} color={Colors.primary} />
            <AppText variant="h3" weight="bold" style={styles.sectionTitleNoMargin}>
              Account for Ayos
            </AppText>
          </View>
          <AppText variant="body" color={Colors.textSecondary} style={{ marginBottom: Spacing['4'] }}>
            Create your user account credentials. This will be used to sign in.
          </AppText>

          <Controller
            control={control}
            rules={{ required: 'Full name is required' }}
            render={({ field: { onChange, onBlur, value } }) => (
              <AppInput
                label="Full Name"
                placeholder="Juan Dela Cruz"
                onBlur={onBlur}
                onChangeText={onChange}
                value={value}
                error={errors.name?.message}
                containerStyle={{ marginBottom: Spacing['4'] }}
              />
            )}
            name="name"
          />

          <Controller
            control={control}
            rules={{ 
              required: 'Mobile number is required',
              pattern: { value: /^[0-9]{11}$/, message: 'Must be 11 digits (e.g. 09171234567)' }
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <AppInput
                label="Mobile Number"
                placeholder="09171234567"
                keyboardType="phone-pad"
                onBlur={onBlur}
                onChangeText={onChange}
                value={value}
                error={errors.mobile?.message}
                containerStyle={{ marginBottom: Spacing['4'] }}
              />
            )}
            name="mobile"
          />

          <Controller
            control={control}
            rules={{ 
              required: 'Email is required',
              pattern: { value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: 'Invalid email' }
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <View style={{ position: 'relative', marginBottom: Spacing['4'] }}>
                <AppInput
                  label="Email Address"
                  placeholder="juan@example.com"
                  keyboardType="email-address"
                  autoCapitalize="none"
                  onBlur={onBlur}
                  onChangeText={(val) => {
                    onChange(val);
                    if (emailVerified) setEmailVerified(false);
                  }}
                  value={value}
                  error={errors.email?.message}
                />
                <View style={{ position: 'absolute', right: 0, top: 28, height: 48, justifyContent: 'center', paddingRight: 12 }}>
                  {emailVerified ? (
                    <Text style={{ color: Colors.success, fontWeight: 'bold' }}>Verified</Text>
                  ) : (
                    <TouchableOpacity onPress={() => value && !errors.email ? setEmailVerified(true) : alert('Please enter a valid email first.')}>
                      <Text style={{ color: Colors.primary, fontWeight: 'bold' }}>Verify</Text>
                    </TouchableOpacity>
                  )}
                </View>
              </View>
            )}
            name="email"
          />

          <Controller
            control={control}
            rules={{ 
              required: 'Password is required',
              minLength: { value: 8, message: 'Minimum 8 characters' }
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <AppInput
                label="Password"
                placeholder="Create password"
                secureTextEntry
                onBlur={onBlur}
                onChangeText={onChange}
                value={value}
                error={errors.password?.message}
                containerStyle={{ marginBottom: Spacing['4'] }}
              />
            )}
            name="password"
          />

          <Controller
            control={control}
            rules={{ 
              required: 'Confirm password is required',
              validate: val => val === password || 'Passwords do not match'
            }}
            render={({ field: { onChange, onBlur, value } }) => (
              <AppInput
                label="Confirm Password"
                placeholder="Confirm password"
                secureTextEntry
                onBlur={onBlur}
                onChangeText={onChange}
                value={value}
                error={errors.confirmPassword?.message}
                containerStyle={{ marginBottom: Spacing['4'] }}
              />
            )}
            name="confirmPassword"
          />

          <View style={styles.consentSection}>
            <Pressable style={styles.checkboxContainer} onPress={() => setAcceptedTerms(!acceptedTerms)}>
              {acceptedTerms ? <Check size={24} color={Colors.primary} /> : <Square size={24} color={Colors.textTertiary} />}
              <AppText variant="bodySm" color={Colors.textSecondary} style={{ flex: 1, marginLeft: Spacing['2'] }}>
                I accept the <AppText variant="bodySm" weight="bold" color={Colors.textLink}>Terms and Conditions</AppText> and <AppText variant="bodySm" weight="bold" color={Colors.textLink}>Privacy Policy</AppText>
              </AppText>
            </Pressable>
          </View>
        </View>
      </ScrollView>

      <View style={[styles.footer, { paddingBottom: keyboardUp ? 10 : 30 }]}>
        <AppButton 
          label="Next Step" 
          onPress={handleSubmit(onSubmit)} 
          loading={loading}
          rightIcon={<ChevronRight size={20} color={Colors.white} />}
          fullWidth 
        />
        <View style={styles.loginContainer}>
          <AppText variant="bodySm" color={Colors.textSecondary}>Already have an account? </AppText>
          <TouchableOpacity onPress={() => router.push('/(auth)/login')}>
            <AppText variant="bodySm" weight="bold" color={Colors.primary}>Log In</AppText>
          </TouchableOpacity>
        </View>
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.surfaceLight,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingTop: 60,
    paddingHorizontal: Spacing['4'],
    paddingBottom: Spacing['4'],
    backgroundColor: Colors.white,
    borderBottomWidth: 1,
    borderBottomColor: Colors.borderLight,
  },
  backButton: {
    padding: Spacing['1'],
  },
  progressContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: Spacing['4'],
    backgroundColor: Colors.white,
    paddingHorizontal: Spacing['8'],
  },
  progressStep: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  progressDot: {
    width: 28,
    height: 28,
    borderRadius: 14,
    backgroundColor: Colors.border,
    justifyContent: 'center',
    alignItems: 'center',
    zIndex: 2,
  },
  progressDotActive: {
    backgroundColor: Colors.primary,
  },
  progressLine: {
    width: 64, // Slightly wider for 2 steps instead of 4
    height: 3,
    backgroundColor: Colors.border,
    marginHorizontal: -4,
    zIndex: 1,
  },
  progressLineActive: {
    backgroundColor: Colors.primary,
  },
  stepLabelsContainer: {
    flexDirection: 'row',
    justifyContent: 'space-around', // Changed to space-around for 2 steps
    paddingHorizontal: Spacing['8'],
    paddingBottom: Spacing['3'],
    backgroundColor: Colors.white,
  },
  scrollContent: {
    paddingHorizontal: Spacing['4'],
    paddingTop: Spacing['6'],
    paddingBottom: Spacing['16'],
  },
  sectionHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: Spacing['2'],
    marginBottom: Spacing['2'],
  },
  sectionTitleNoMargin: {
    marginBottom: 0,
  },
  formSection: {
    marginBottom: Spacing['4'],
  },
  consentSection: {
    marginTop: Spacing['2'],
    marginBottom: Spacing['4'],
  },
  checkboxContainer: {
    flexDirection: 'row',
    alignItems: 'flex-start',
  },
  footer: {
    padding: Spacing['4'],
    backgroundColor: Colors.white,
    borderTopWidth: 1,
    borderTopColor: Colors.borderLight,
  },
  loginContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    marginTop: Spacing['4'],
  },
});

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { View, Text, StyleSheet, ScrollView, Pressable, Alert, Animated } from 'react-native';
import { Image } from 'expo-image';
import {
  ArrowLeft,
  MapPin,
  Clock,
  Calendar,
  Phone,
  MessageSquare,
  CheckCircle2,
  Loader2,
  XCircle,
  Wrench,
  Banknote,
  PhilippinePeso,
  User,
  FileText,
  ShieldAlert,
} from 'lucide-react-native';
import { router, useLocalSearchParams } from 'expo-router';
import { Colors, Radius, Spacing, Elevation, Layout, AvatarSize } from '@/constants/theme';
import { AppText } from '@/components/AppText';
import { AppButton } from '@/components/AppButton';
import { Badge } from '@/components/Badge';
import { Avatar } from '@/components/Avatar';
import { ThreeDotMenu } from '@/components/ThreeDotMenu';
import { BookingStepIndicator } from '@/components/booking/BookingStepIndicator';
import { BookingMap } from '@/components/booking/BookingMap';
// import { JobTimer } from '@/components/booking/JobTimer';
import { CompletedSummary } from '@/components/booking/CompletedSummary';
import { RescheduleDialog } from '@/components/booking/RescheduleDialog';
import { WorkerSOSModal } from '@/components/booking/WorkerSOSModal';
import { JobCompletionModal } from '@/components/booking/JobCompletionModal';
import { getBackRoute } from '@/constants/backRoutes';
import { statusConfig } from '@/constants/workerMockData';
import { useWorkerBookings, useWorkerJobs } from '@/hooks';
import { useWorkerBookingStore } from '@/store/useWorkerBookingStore';
import type { WorkerBooking } from '@/constants/workerMockData';

export default function BookingRequestScreen() {
  const { id, autoAccept, from } = useLocalSearchParams<{ id: string; autoAccept?: string; from?: string }>();
  const { data: workerBookings = [] } = useWorkerBookings();
  const { data: workerJobs = [] } = useWorkerJobs();
  const job = useMemo(() => workerJobs.find((j) => j.id === id) || workerJobs[0], [id]);

  const [statusOverrides, setStatusOverrides] = useState<Record<string, WorkerBooking['status']>>(() => {
    if (autoAccept === 'true' && id) {
      const base = workerBookings.find((b) => b.id === id);
      if (base?.status === 'hired') return { [base.id]: 'accepted' as WorkerBooking['status'] };
    }
    return {};
  });

  const storeBookingId = useWorkerBookingStore((s) => s.currentBookingId);
  const storeStatus = useWorkerBookingStore((s) => s.currentStatus);

  const booking = useMemo(() => {
    const base = workerBookings.find((b) => b.id === id) || workerBookings[0];
    const storeOverride = (storeBookingId === base.id && storeStatus) ? storeStatus : null;
    const localOverride = statusOverrides[base.id] || null;
    const effectiveStatus = storeOverride || localOverride || base.status;
    return { ...base, status: effectiveStatus };
  }, [id, statusOverrides, storeStatus, storeBookingId]);

  const setStoreStatus = useWorkerBookingStore((s) => s.setStatus);
  const setCompletionTimer = useWorkerBookingStore((s) => s.setCompletionTimer);
  const clearCurrentBooking = useWorkerBookingStore((s) => s.clearCurrentBooking);
  const completionTimestamp = useWorkerBookingStore((s) => s.completionTimestamp);
  const completionData = useWorkerBookingStore((s) => s.completionData);
  const setStoreCompletionData = useWorkerBookingStore((s) => s.setCompletionData);

  useEffect(() => {
    return () => {
      const status = useWorkerBookingStore.getState().currentStatus;
      if (status === 'in_progress') {
        clearCurrentBooking();
      }
    };
  }, []);



  const updateStatus = (newStatus: WorkerBooking['status']) => {
    if (newStatus === 'pending_review') {
      setCompletionTimer();
    }
    setStatusOverrides((prev) => ({ ...prev, [booking.id]: newStatus }));
    setStoreStatus(booking.id, newStatus);
  };

  useEffect(() => {
    if (autoAccept === 'true' && booking.status === 'hired') {
      updateStatus('accepted');
    }
  }, [autoAccept, booking.status]);

  useEffect(() => {
    if (booking.status === 'pending_review' && !completionTimestamp) {
      setCompletionTimer();
    }
  }, [booking.status]);

  const [showRescheduleDialog, setShowRescheduleDialog] = useState(false);
  const [showSOS, setShowSOS] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<'cash' | 'online' | null>(null);
  const [rescheduleData, setRescheduleData] = useState<{
    status: 'pending' | 'accepted' | 'rejected';
    date: string;
    time: string;
  } | null>(null);

  const handleRescheduleConfirm = (date: string, time: string, message: string) => {
    setRescheduleData({ status: 'pending', date: date.trim(), time: time.trim() });
    setShowRescheduleDialog(false);
    Alert.alert(
      'Reschedule Proposed',
      `New date: ${date}\nNew time: ${time}${message ? `\nMessage: ${message}` : ''}\n\nThe customer will be notified.`
    );
  };

  const cycleReschedule = () => {
    setRescheduleData((prev) => {
      if (prev?.status === 'pending') return { ...prev, status: 'accepted' as const };
      if (prev?.status === 'accepted') return { ...prev, status: 'rejected' as const };
      return null;
    });
  };

  const handleConfirmDetails = () => {
    Alert.alert('Confirm Details', 'Are you sure you want to confirm the details and head to the location?', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Proceed', onPress: () => updateStatus('en_route') },
    ]);
  };

  const handleArrived = () => {
    Alert.alert('Arrived at Location', 'You have arrived at the customer\'s location. Start the job when ready.', [
      { text: 'OK', onPress: () => updateStatus('arrived') },
    ]);
  };

  const handleComplete = () => {
    setPendingAction('online');
    setShowCompletionModal(true);
  };

  const handleCompletionSubmit = (data: { completionImages: string[]; completionVideo: string | null; workerRating: number; workerReview: string }) => {
    setStoreCompletionData(data);
    setShowCompletionModal(false);

    if (pendingAction === 'cash') {
      router.push(`/(worker)/cash-confirm/${booking.id}`);
    } else if (pendingAction === 'online') {
      updateStatus('pending_review');
    }
    setPendingAction(null);
  };

  const handleCompletionModalClose = () => {
    setShowCompletionModal(false);
    setPendingAction(null);
  };

  useEffect(() => {
    if (booking.status !== 'pending_review' || !completionTimestamp) return;
    const remaining = completionTimestamp - Date.now();
    if (remaining <= 0) {
      updateStatus('completed');
      return;
    }
    const timer = setTimeout(() => {
      updateStatus('completed');
    }, remaining);
    return () => clearTimeout(timer);
  }, [booking.status, completionTimestamp]);

  const handleReport = () => {
    router.push(`/(worker)/report-user/${booking.id}?from=/(detail)/booking-request/${booking.id}`);
  };

  const handleCancelService = () => {
    router.push(`/(worker)/cancel-service/${booking.id}?from=${from || 'dashboard'}`);
  };

  const handleBack = () => {
    if (from === 'chat') {
      router.back();
      return;
    }
    const route = getBackRoute(from);
    route ? router.push(route) : router.back();
  };

  const isCompleted = booking.status === 'completed';
  const isCancelled = booking.status === 'cancelled';

  const [remainingTime, setRemainingTime] = useState('');
  const spinAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (booking.status !== 'pending_review') return;
    const remaining = completionTimestamp ? completionTimestamp - Date.now() : 0;
    const duration = remaining > 0 && remaining < 10000 ? 500 : 2000;
    const loop = Animated.loop(
      Animated.timing(spinAnim, { toValue: 1, duration, useNativeDriver: true })
    );
    loop.start();
    return () => loop.stop();
  }, [booking.status, completionTimestamp, remainingTime]);

  useEffect(() => {
    if (booking.status !== 'pending_review' || !completionTimestamp) {
      setRemainingTime('');
      return;
    }
    const update = () => {
      const remaining = completionTimestamp - Date.now();
      if (remaining <= 0) {
        setRemainingTime('Auto-confirming...');
      } else {
        setRemainingTime(`${Math.ceil(remaining / 1000)}s`);
      }
    };
    update();
    const interval = setInterval(update, 500);
    return () => clearInterval(interval);
  }, [booking.status, completionTimestamp]);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Pressable style={styles.backButton} onPress={handleBack} hitSlop={12}>
          <ArrowLeft size={24} color={Colors.textPrimary} />
        </Pressable>
        <AppText variant="h4" weight="bold" color={Colors.textPrimary}>
          Booking Request
        </AppText>
        {['hired', 'accepted', 'en_route', 'arrived', 'in_progress'].includes(booking.status) && !booking.isReported ? (
          <Pressable style={styles.sosButton} onPress={() => setShowSOS(true)}>
            <Text style={styles.sosText}>SOS</Text>
          </Pressable>
        ) : (
          <View style={{ width: 40 }} />
        )}
      </View>

      <ScrollView
        style={styles.scrollView}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        {/* ─── Job Card ─── */}
        <View style={styles.jobCard}>
          <BookingStepIndicator currentStatus={booking.status} />

          <View style={styles.statusBadgeRow}>
            <Badge
              label={statusConfig[booking.status]?.label || booking.status}
              variant={(statusConfig[booking.status]?.variant as any) || 'info'}
              size="sm"
            />
            {booking.status === 'accepted' && (
              <Badge label="Worker Preparing" variant="info" size="sm" />
            )}
            {booking.status === 'in_progress' && (
              <>
                <Badge label="Service Started" variant="success" size="sm" />
                <Badge label="Currently Working" variant="warning" size="sm" />
              </>
            )}
          </View>

          <View style={styles.cardTopRow}>
            <AppText variant="h3" weight="bold" style={{ flex: 1 }}>
              {job.service}
            </AppText>
            <ThreeDotMenu
              onReportUser={handleReport}
              onCancelService={handleCancelService}
              showCancel={!isCompleted && !isCancelled && booking.status !== 'pending_review'}
            />
          </View>

          <AppText variant="caption" color={Colors.textTertiary}>
            Booking #{booking.id.padStart(4, '0')}
          </AppText>

          <View style={styles.infoBadgeRow}>
            {job.urgency === 'urgent' && (
              <Badge label="URGENT" variant="error" size="sm" />
            )}
            <Badge
              label={booking.paymentMethod === 'cash' ? 'Cash Payment' : 'Online Payment'}
              variant={booking.paymentMethod === 'cash' ? 'warning' : 'info'}
              size="sm"
            />
            {booking.pricingType === 'hourly' && (
              <Badge label="Hourly Rate" variant="neutral" size="sm" />
            )}
          </View>

          {job.imageUrl && (
            <Image source={{ uri: job.imageUrl }} style={styles.jobImage} resizeMode="cover" />
          )}

          <AppText variant="body" color={Colors.textSecondary} style={styles.description}>
            "{job.description}"
          </AppText>

          {booking.notes && (
            <>
              <View style={styles.divider} />
              <View style={styles.voiceTranscriptSection}>
                <View style={styles.detailLabel}>
                  <FileText size={14} color={Colors.cta} />
                  <AppText variant="label" weight="semiBold" color={Colors.cta}>Additional Notes</AppText>
                </View>
                <AppText variant="bodySm" color={Colors.textSecondary} style={styles.voiceTranscriptText}>
                  {booking.notes}
                </AppText>
              </View>
            </>
          )}

          {(booking.urgency || booking.possibleCause || booking.voiceTranscript) && (
            <View style={styles.analysisCard}>
              {booking.urgency && (
                <View style={styles.analysisRow}>
                  <AppText variant="label" weight="semiBold" color={Colors.textSecondary}>Urgency</AppText>
                  <AppText variant="bodySm" color={Colors.textSecondary}>{booking.urgency}</AppText>
                </View>
              )}
              {booking.possibleCause && (
                <View style={styles.analysisRow}>
                  <AppText variant="label" weight="semiBold" color={Colors.textSecondary}>Possible Cause</AppText>
                  <AppText variant="bodySm" color={Colors.textSecondary}>{booking.possibleCause}</AppText>
                </View>
              )}
              {booking.voiceTranscript && (
                <View style={styles.analysisRow}>
                  <AppText variant="label" weight="semiBold" color={Colors.textSecondary}>AI Voice Transcript</AppText>
                  <AppText variant="bodySm" color={Colors.textSecondary} style={styles.voiceTranscriptText}>
                    {booking.voiceTranscript}
                  </AppText>
                </View>
              )}
            </View>
          )}

          <View style={styles.divider} />

          <View style={styles.detailRow}>
            <View style={styles.detailLabel}>
              <User size={14} color={Colors.textTertiary} />
              <AppText variant="label" color={Colors.textTertiary}>Client</AppText>
            </View>
            <AppText variant="body" weight="semiBold">{job.customerName}</AppText>
          </View>

          <View style={styles.detailRow}>
            <View style={styles.detailLabel}>
              <MapPin size={14} color={Colors.textTertiary} />
              <AppText variant="label" color={Colors.textTertiary}>Location</AppText>
            </View>
            <AppText variant="body" weight="semiBold">{job.location}</AppText>
          </View>

          <View style={styles.detailRow}>
            <View style={styles.detailLabel}>
              <Clock size={14} color={Colors.textTertiary} />
              <AppText variant="label" color={Colors.textTertiary}>Schedule</AppText>
            </View>
            <AppText variant="body" weight="semiBold">
              {booking.date} · {booking.time}
            </AppText>
          </View>

          <View style={styles.detailRow}>
            <View style={styles.detailLabel}>
              <PhilippinePeso size={14} color={Colors.textTertiary} />
              <AppText variant="label" color={Colors.textTertiary}>
                {booking.pricingType === 'hourly' ? 'Est. Earnings (Hourly)' : 'Est. Earnings'}
              </AppText>
            </View>
            <AppText variant="body" weight="semiBold" color={Colors.cta}>
              {booking.pricingType === 'hourly' ? `₱${booking.hourlyRate}/hr` : booking.price}
            </AppText>
          </View>

          {booking.serviceType && (
            <>
              <View style={styles.divider} />
              <View style={styles.detailRow}>
                <View style={styles.detailLabel}>
                  <Wrench size={14} color={Colors.textTertiary} />
                  <AppText variant="label" color={Colors.textTertiary}>Service Type</AppText>
                </View>
                <AppText variant="body" weight="semiBold">{booking.serviceType}</AppText>
              </View>
            </>
          )}

          {booking.safetyAdvice && (
            <>
              <View style={styles.divider} />
              <AppText variant="label" weight="semiBold" color={Colors.textSecondary}>Safety Advice</AppText>
              <View style={styles.safetyAdviceBox}>
                <ShieldAlert size={20} color={Colors.error} />
                <AppText variant="bodySm" color={Colors.error} style={{ flex: 1 }}>
                  {booking.safetyAdvice}
                </AppText>
              </View>
            </>
          )}
        </View>

        {rescheduleData && (
          <Pressable style={styles.rescheduleCard} onPress={cycleReschedule}>
            <View style={[styles.rescheduleIcon, {
              backgroundColor: rescheduleData.status === 'pending' ? Colors.warningBg : rescheduleData.status === 'accepted' ? Colors.successBg : Colors.errorBg,
            }]}>
              {rescheduleData.status === 'pending' && <Clock size={20} color={Colors.warning} />}
              {rescheduleData.status === 'accepted' && <CheckCircle2 size={20} color={Colors.success} />}
              {rescheduleData.status === 'rejected' && <XCircle size={20} color={Colors.error} />}
            </View>
            <View style={styles.rescheduleBody}>
              <AppText variant="bodySm" weight="semiBold">
                {rescheduleData.status === 'pending' ? 'Reschedule Pending' : rescheduleData.status === 'accepted' ? 'Reschedule Accepted' : 'Reschedule Rejected'}
              </AppText>
              <AppText variant="caption" color={Colors.textSecondary}>
                Proposed: {rescheduleData.date} at {rescheduleData.time}
              </AppText>
              <AppText variant="caption" color={rescheduleData.status === 'pending' ? Colors.textTertiary : rescheduleData.status === 'accepted' ? Colors.success : Colors.error}>
                {rescheduleData.status === 'pending' ? 'Awaiting customer response...' : rescheduleData.status === 'accepted' ? 'The customer agreed to the new schedule.' : 'The customer declined the reschedule.'}
              </AppText>
            </View>
          </Pressable>
        )}

        {/* ─── Client Card ─── */}
        <View style={styles.clientCard}>
          <View style={styles.clientHeader}>
            <Avatar uri={job.customerAvatar} size={AvatarSize.medium} />
            <View style={styles.clientInfo}>
              <AppText variant="body" weight="semiBold">{job.customerName}</AppText>
              <AppText variant="caption" color={Colors.textSecondary}>
                4 bookings · No cancellations
              </AppText>
            </View>
          </View>
          <Badge label="Good client" variant="success" size="sm" />
        </View>

        {/* ─── State-Specific Content ─── */}
        {booking.status === 'hired' && (
          <View style={styles.hiredBanner}>
            <View style={styles.hiredIconRow}>
              <Calendar size={28} color={Colors.cta} />
            </View>
            <AppText variant="h3" weight="bold" style={styles.hiredTitle}>
              You've Been Selected!
            </AppText>
            <AppText variant="body" color={Colors.textSecondary} style={styles.hiredSubtitle}>
              {job.customerName} has selected you for this job. Accept to start coordinating.
            </AppText>
            <View style={styles.hiredActions}>
              <AppButton
                label="Accept Booking"
                variant="primary"
                leftIcon={<Calendar size={18} color={Colors.white} />}
                fullWidth
                onPress={() => {
                  Alert.alert(
                    'Accept Booking',
                    'Accept this booking request and start coordinating with the customer?',
                    [
                      { text: 'Cancel', style: 'cancel' },
                      { text: 'Accept', onPress: () => updateStatus('accepted') },
                    ]
                  );
                }}
              />
              <AppButton
                label="Reschedule"
                variant="outline"
                fullWidth
                onPress={() => setShowRescheduleDialog(true)}
              />
            </View>
          </View>
        )}

        {booking.status === 'accepted' && (
          <>
            <Pressable
              style={styles.chatCustomerBtn}
              onPress={() => router.push(`/messages/chat?id=${booking.id}`)}
            >
              <MessageSquare size={20} color={Colors.cta} />
              <AppText variant="body" weight="semiBold" color={Colors.cta}>
                Chat with customer
              </AppText>
            </Pressable>
            <Pressable
              style={styles.confirmDetailsBtn}
              onPress={handleConfirmDetails}
            >
              <AppText variant="body" weight="semiBold" color={Colors.white}>
                ✓ Confirm Details
              </AppText>
            </Pressable>
          </>
        )}

        {booking.status === 'en_route' && (
          <>
            <BookingMap
              destinationLat={booking.lat}
              destinationLng={booking.lng}
              destinationAddress={booking.address}
            />
            <View style={styles.contactRow}>
              <Pressable style={styles.contactBtn} onPress={() => Alert.alert('Call', 'Calling customer...')}>
                <Phone size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Call</AppText>
              </Pressable>
              <Pressable style={styles.contactBtn} onPress={() => router.push(`/messages/chat?id=${booking.id}`)}>
                <MessageSquare size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Message</AppText>
              </Pressable>
            </View>
            <AppButton
              label="I've Arrived"
              variant="primary"
              leftIcon={<MapPin size={18} color={Colors.white} />}
              fullWidth
              onPress={handleArrived}
            />
          </>
        )}

        {booking.status === 'arrived' && (
          <>
            <BookingMap
              destinationLat={booking.lat}
              destinationLng={booking.lng}
              destinationAddress={booking.address}
            />
            <View style={styles.contactRow}>
              <Pressable style={styles.contactBtn} onPress={() => Alert.alert('Call', 'Calling customer...')}>
                <Phone size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Call</AppText>
              </Pressable>
              <Pressable style={styles.contactBtn} onPress={() => router.push(`/messages/chat?id=${booking.id}`)}>
                <MessageSquare size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Message</AppText>
              </Pressable>
            </View>
            <AppButton
              label="Start Job"
              variant="primary"
              leftIcon={<CheckCircle2 size={18} color={Colors.white} />}
              fullWidth
              onPress={() => {
                Alert.alert('Start Job', 'Begin working on this job?', [
                  { text: 'Cancel', style: 'cancel' },
                  { text: 'Start', onPress: () => updateStatus('in_progress') },
                ]);
              }}
            />
          </>
        )}

        {booking.status === 'in_progress' && (
          <>
            {/* <JobTimer hourlyRate={booking.pricingType === 'hourly' ? booking.hourlyRate : undefined} /> */}
            <View style={styles.contactRow}>
              <Pressable style={styles.contactBtn} onPress={() => Alert.alert('Call', 'Calling customer...')}>
                <Phone size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Call</AppText>
              </Pressable>
              <Pressable style={styles.contactBtn} onPress={() => router.push(`/messages/chat?id=${booking.id}`)}>
                <MessageSquare size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Message</AppText>
              </Pressable>
            </View>
            {booking.paymentMethod === 'cash' ? (
              <AppButton
                label="Collect Cash Payment"
                variant="primary"
                leftIcon={<Banknote size={18} color={Colors.white} />}
                fullWidth
                onPress={() => {
                  setPendingAction('cash');
                  setShowCompletionModal(true);
                }}
              />
            ) : (
              <AppButton
                label="Complete Job"
                variant="primary"
                leftIcon={<CheckCircle2 size={18} color={Colors.white} />}
                fullWidth
                onPress={handleComplete}
              />
            )}
          </>
        )}

        {booking.status === 'pending_review' && (
          <View style={styles.reviewCard}>
            <Animated.View style={{
              transform: [{
                rotate: spinAnim.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '360deg'] })
              }]
            }}>
              <Loader2 size={36} color={Colors.warning} style={styles.spinner} />
            </Animated.View>
            <AppText variant="h4" weight="bold" style={styles.reviewTitle}>
              Waiting for Customer
            </AppText>
            <AppText variant="body" color={Colors.textSecondary} style={styles.reviewSubtitle}>
              The customer has been notified to confirm the job completion.
            </AppText>
            {remainingTime && (
              <View style={styles.timeoutBadge}>
                <Clock size={14} color={Colors.textTertiary} />
                <AppText variant="caption" color={Colors.textSecondary}>
                  Auto-confirms in {remainingTime}
                </AppText>
              </View>
            )}
            <View style={styles.contactRow}>
              <Pressable style={styles.contactBtn} onPress={() => Alert.alert('Call', 'Calling customer...')}>
                <Phone size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Call</AppText>
              </Pressable>
              <Pressable style={styles.contactBtn} onPress={() => router.push(`/messages/chat?id=${booking.id}`)}>
                <MessageSquare size={18} color={Colors.cta} />
                <AppText variant="bodySm" weight="semiBold" color={Colors.cta}>Message</AppText>
              </Pressable>
            </View>
          </View>
        )}

        {isCompleted && (
          <CompletedSummary
            bookingId={booking.id}
            duration="1h 15m"
            earnings={booking.price}
            description={job.description}
            completionImages={completionData?.completionImages ?? booking.completionImages}
            completionVideo={completionData?.completionVideo ?? booking.completionVideo}
            workerRating={completionData?.workerRating ?? booking.workerRating}
            workerReview={completionData?.workerReview ?? booking.workerReview}
            onViewReceipt={() => router.push(`/(worker)/earnings-receipt?bookingId=${booking.id}&duration=1h 15m&earnings=${encodeURIComponent(booking.price)}&from=/(detail)/booking-request/${booking.id}`)}
          />
        )}

        {isCancelled && (
          <View style={styles.cancelledBanner}>
            {booking.cancelledBy === 'worker' ? (
              <>
                <XCircle size={36} color={Colors.warning} />
                <AppText variant="h4" weight="bold" color={Colors.warning}>Booking Cancelled</AppText>
                <AppText variant="body" color={Colors.textSecondary} style={{ textAlign: 'center' }}>
                  You have cancelled this booking.
                </AppText>
              </>
            ) : (
              <>
                <XCircle size={36} color={Colors.error} />
                <AppText variant="h4" weight="bold" color={Colors.error}>Booking Cancelled</AppText>
                <AppText variant="body" color={Colors.textSecondary} style={{ textAlign: 'center' }}>
                  The customer has cancelled this booking.
                </AppText>
              </>
            )}
            {booking.cancelledReason && (
              <AppText variant="caption" color={Colors.textTertiary} style={{ textAlign: 'center', fontStyle: 'italic' }}>
                Reason: {booking.cancelledReason}
              </AppText>
            )}
          </View>
        )}
      </ScrollView>

      <RescheduleDialog
        visible={showRescheduleDialog}
        onClose={() => setShowRescheduleDialog(false)}
        onConfirm={handleRescheduleConfirm}
        customerName={job.customerName}
      />

      <WorkerSOSModal
        visible={showSOS}
        onClose={() => setShowSOS(false)}
        bookingId={booking.id}
        customerName={job.customerName}
      />

      <JobCompletionModal
        visible={showCompletionModal}
        onClose={handleCompletionModalClose}
        onSubmit={handleCompletionSubmit}
        customerName={job.customerName}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: Colors.background },
  header: {
    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
    backgroundColor: Colors.white, paddingHorizontal: Layout.screenPadding,
    paddingTop: Spacing['16'], paddingBottom: Spacing['4'],
    borderBottomWidth: 1, borderBottomColor: Colors.borderLight,
  },
  backButton: {
    width: 40, height: 40, borderRadius: Radius.full,
    alignItems: 'center', justifyContent: 'center',
  },
  sosButton: {
    backgroundColor: '#fef2f2', paddingHorizontal: 12, paddingVertical: 6,
    borderRadius: Radius.full, borderWidth: 1, borderColor: '#fecaca',
  },
  sosText: { color: Colors.error, fontWeight: 'bold', fontSize: 13 },
  scrollView: { flex: 1 },
  scrollContent: {
    padding: Layout.screenPadding, paddingBottom: Spacing['10'], gap: Spacing['4'],
  },
  jobCard: {
    backgroundColor: Colors.white, borderRadius: Radius.xl,
    padding: Layout.cardPadding, gap: Spacing['3'], ...Elevation.sm,
