import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, ScrollView, Modal, TextInput, KeyboardAvoidingView, Platform, Keyboard } from 'react-native';
import { useRouter } from 'expo-router';
import { Screen } from '@/components/layout/Screen';
import { AppButton } from '@/components/AppButton';
import { AppInput } from '@/components/AppInput';
import { theme } from '@/constants/theme';
import { ArrowLeft, User, Mail, Phone, X } from 'lucide-react-native';
import { useAuthStore } from '@/store/useAuthStore';

export default function AccountScreen() {
  const router = useRouter();
  const { user, updateUser } = useAuthStore();
  const [isEditing, setIsEditing] = useState(false);
  const [editingField, setEditingField] = useState<{ id: string, title: string, value: string, field: 'name' | 'email' | 'phone' } | null>(null);
  const [editValue, setEditValue] = useState('');

  const INFO_ITEMS = [
    { id: '1', title: 'Name', value: user?.name || 'Juan Dela Cruz', icon: User, field: 'name' as const },
    { id: '2', title: 'Email Address', value: user?.email || 'juan.delacruz@example.com', icon: Mail, field: 'email' as const },
    { id: '3', title: 'Phone Number', value: user?.phone || '0917 123 4567', icon: Phone, field: 'phone' as const },
  ];

  const handleEdit = (item: typeof INFO_ITEMS[0]) => {
    setEditingField(item);
    setEditValue(item.value);
    setIsEditing(true);
  };

  const handleSave = () => {
    if (editingField && editValue.trim() !== '') {
      updateUser({ [editingField.field]: editValue.trim() });
    }
    setIsEditing(false);
    Keyboard.dismiss();
  };

  return (
    <Screen safeArea backgroundColor={theme.colors.background}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => router.back()} style={styles.backButton}>
          <ArrowLeft color={theme.colors.textPrimary} size={24} />
        </TouchableOpacity>
        <Text style={[theme.typography.h4, { color: theme.colors.textPrimary }]}>Personal Information</Text>
        <View style={{ width: 40 }} />
      </View>

      <ScrollView showsVerticalScrollIndicator={false} style={styles.content}>
        <View style={styles.section}>
          <View style={styles.card}>
            {INFO_ITEMS.map((item, index) => {
              const Icon = item.icon;
              return (
                <View key={item.id} style={[styles.infoRow, index !== INFO_ITEMS.length - 1 && styles.borderBottom]}>
                  <View style={styles.iconContainer}>
                    <Icon color={theme.colors.textSecondary} size={20} />
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={theme.typography.caption}>{item.title}</Text>
                    <Text style={[theme.typography.body1, { marginTop: 2 }]}>{item.value}</Text>
                  </View>
                  <TouchableOpacity onPress={() => handleEdit(item)}>
                    <Text style={[theme.typography.button, { color: theme.colors.primary, fontSize: 14 }]}>Edit</Text>
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        </View>
      </ScrollView>

      {/* Edit Modal */}
      <Modal visible={isEditing} transparent animationType="slide">
        <KeyboardAvoidingView 
          style={styles.modalOverlay} 
          behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        >
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={theme.typography.h3}>Edit {editingField?.title}</Text>
              <TouchableOpacity onPress={() => setIsEditing(false)} style={styles.closeBtn}>
                <X color={theme.colors.textSecondary} size={24} />
              </TouchableOpacity>
            </View>
            
            <AppInput 
              label={editingField?.title || ''}
              value={editValue}
              onChangeText={setEditValue}
              placeholder={`Enter new ${editingField?.title.toLowerCase()}`}
              keyboardType={editingField?.field === 'email' ? 'email-address' : editingField?.field === 'phone' ? 'phone-pad' : 'default'}
              autoCapitalize={editingField?.field === 'email' ? 'none' : 'words'}
              autoFocus
              containerStyle={{ marginBottom: theme.spacing.xl }}
            />
            
            <AppButton 
              label="Save Changes"
              onPress={handleSave}
              fullWidth
            />
          </View>
        </KeyboardAvoidingView>
      </Modal>
    </Screen>
  );
}

const styles = StyleSheet.create({
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: theme.spacing.md, paddingHorizontal: theme.layout.screenPadding },
  backButton: { width: 40, height: 40, justifyContent: 'center', alignItems: 'flex-start' },
  content: { flex: 1, paddingHorizontal: theme.layout.screenPadding, paddingTop: theme.spacing.md },
  
  section: { marginBottom: theme.spacing.xl },
  
  card: { backgroundColor: theme.colors.surface, borderRadius: theme.radius.lg, ...theme.shadows.sm, overflow: 'hidden' },
  infoRow: { flexDirection: 'row', alignItems: 'center', padding: theme.spacing.md },
  borderBottom: { borderBottomWidth: 1, borderBottomColor: theme.colors.borderLight },
  iconContainer: { width: 40, height: 40, borderRadius: 20, backgroundColor: theme.colors.background, justifyContent: 'center', alignItems: 'center', marginRight: theme.spacing.md },
  
  modalOverlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'flex-end' },
  modalContent: { backgroundColor: theme.colors.background, borderTopLeftRadius: theme.radius.xl, borderTopRightRadius: theme.radius.xl, padding: theme.spacing.xl, paddingBottom: 40 },
  modalHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: theme.spacing.xl },
  closeBtn: { padding: theme.spacing.xs },
});

import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, ScrollView, TextInput, Switch, Modal, Alert } from 'react-native';
import { useRouter } from 'expo-router';
import { Screen } from '@/components/layout/Screen';
import { AppButton } from '@/components/AppButton';
import { theme } from '@/constants/theme';
import { ArrowLeft, UploadCloud, AlertTriangle, CheckCircle2, ShieldOff, Image as ImageIcon } from 'lucide-react-native';

export default function ReportUserScreen() {
  const router = useRouter();
  
  const [userName, setUserName] = useState('');
  const [description, setDescription] = useState('');
  const [blockUser, setBlockUser] = useState(false);
  const [evidenceUploaded, setEvidenceUploaded] = useState(false);
  
  const [loading, setLoading] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const handleSubmit = () => {
    if (!userName.trim() || !description.trim()) {
      Alert.alert('Missing Details', "Please provide the user's name and describe the incident.");
      return;
    }
    
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setShowSuccess(true);
    }, 1500);
  };

  const handleFinish = () => {
    setShowSuccess(false);
    router.back();
  };

  return (
    <Screen safeArea scrollable>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => router.back()} style={styles.backButton}>
          <ArrowLeft color={theme.colors.textPrimary} size={24} />
        </TouchableOpacity>
        <Text style={[theme.typography.h4, { color: theme.colors.textPrimary }]}>Report & Block</Text>
        <View style={{ width: 40 }} />
      </View>

      <ScrollView style={styles.content} showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingBottom: 40 }}>
        
        <View style={styles.warningBox}>
          <AlertTriangle color={theme.colors.warning} size={24} style={{ marginRight: 12 }} />
          <Text style={[theme.typography.body2, { flex: 1, color: theme.colors.textSecondary }]}>
            We take reports seriously. Misuse of this feature may result in account penalties.
          </Text>
        </View>

        <View style={styles.formGroup}>
          <Text style={styles.label}>User to Report</Text>
          <TextInput 
            style={styles.input}
            placeholder="Enter the worker or customer's name"
            value={userName}
            onChangeText={setUserName}
          />
        </View>

        <View style={styles.formGroup}>
          <Text style={styles.label}>Describe the Incident</Text>
          <TextInput 
            style={[styles.input, styles.textArea]}
            placeholder="Please provide details about what happened..."
            value={description}
            onChangeText={setDescription}
            multiline
            textAlignVertical="top"
          />
        </View>

        <View style={styles.formGroup}>
          <Text style={styles.label}>Upload Evidence (Optional)</Text>
          <Text style={[theme.typography.caption, { color: theme.colors.textTertiary, marginBottom: 8 }]}>Screenshots or photos related to the incident</Text>
          
          <TouchableOpacity 
            style={[styles.uploadBox, evidenceUploaded && styles.uploadBoxSuccess]} 
            onPress={() => setEvidenceUploaded(true)}
            activeOpacity={0.7}
          >
            {evidenceUploaded ? (
              <>
                <CheckCircle2 color={theme.colors.success} size={28} style={{ marginBottom: 8 }} />
                <Text style={[theme.typography.body2, { color: theme.colors.success, fontWeight: 'bold' }]}>Evidence Attached</Text>
              </>
            ) : (
              <>
                <UploadCloud color={theme.colors.textSecondary} size={28} style={{ marginBottom: 8 }} />
                <Text style={[theme.typography.body2, { color: theme.colors.textSecondary }]}>Tap to attach photos</Text>
              </>
            )}
          </TouchableOpacity>
        </View>

        <View style={styles.blockSection}>
          <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center' }}>
            <ShieldOff color={theme.colors.error} size={20} style={{ marginRight: 12 }} />
            <View>
              <Text style={[theme.typography.body1, { fontWeight: '600' }]}>Block this user</Text>
              <Text style={[theme.typography.caption, { color: theme.colors.textSecondary }]}>They won't be able to contact you.</Text>
            </View>
          </View>
          <Switch 
            value={blockUser} 
            onValueChange={setBlockUser}
            trackColor={{ false: theme.colors.border, true: theme.colors.error }}
            thumbColor={'#fff'}
          />
        </View>

        <AppButton 
          label="Submit Report" 
          onPress={handleSubmit} 
          loading={loading}
          style={styles.submitBtn}
        />
      </ScrollView>

      {/* Success Modal */}
      <Modal visible={showSuccess} transparent animationType="fade">
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <CheckCircle2 color={theme.colors.success} size={64} style={{ marginBottom: 16 }} />
            <Text style={[theme.typography.h3, { marginBottom: 8, textAlign: 'center' }]}>Report Submitted</Text>
            <Text style={[theme.typography.body2, { color: theme.colors.textSecondary, textAlign: 'center', marginBottom: 24 }]}>
              Thank you for keeping the A-yos community safe. Our support team will review this incident shortly.
            </Text>
            <AppButton label="Done" onPress={handleFinish} fullWidth />
          </View>
        </View>
      </Modal>

    </Screen>
  );
}

const styles = StyleSheet.create({
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: theme.spacing.md, paddingHorizontal: theme.layout.screenPadding },
  backButton: { width: 40, height: 40, justifyContent: 'center', alignItems: 'flex-start' },
  content: { flex: 1, paddingHorizontal: theme.layout.screenPadding },
  
  warningBox: { flexDirection: 'row', backgroundColor: '#fffbeb', padding: 16, borderRadius: theme.radius.md, borderWidth: 1, borderColor: '#fde68a', marginBottom: 24, alignItems: 'center' },
  
  formGroup: { marginBottom: 20 },
  label: { ...theme.typography.label, fontWeight: '600', color: theme.colors.textPrimary, marginBottom: 8 },
  input: { backgroundColor: theme.colors.surface, borderWidth: 1, borderColor: theme.colors.border, borderRadius: theme.radius.md, padding: 16, ...theme.typography.body1 },
  textArea: { height: 120 },
  
  uploadBox: { borderWidth: 2, borderStyle: 'dashed', borderColor: theme.colors.border, borderRadius: theme.radius.md, padding: 24, backgroundColor: theme.colors.background, justifyContent: 'center', alignItems: 'center' },
  uploadBoxSuccess: { borderColor: theme.colors.success, backgroundColor: '#f0fdf4', borderStyle: 'solid' },

  blockSection: { flexDirection: 'row', alignItems: 'center', backgroundColor: '#fef2f2', padding: 16, borderRadius: theme.radius.md, borderWidth: 1, borderColor: '#fecaca', marginBottom: 32 },

  submitBtn: { backgroundColor: theme.colors.error },

  modalOverlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'center', alignItems: 'center', padding: theme.layout.screenPadding },
  modalContent: { backgroundColor: theme.colors.surface, borderRadius: theme.radius.xl, padding: 32, alignItems: 'center', width: '100%' },
});

import React, { useRef, useEffect } from 'react';
import { View, TouchableOpacity, StyleSheet, Animated, Platform } from 'react-native';
import { Tabs, useRouter } from 'expo-router';
import { theme } from '@/constants/theme';
import { Home, FileText, MessageSquare, User, Plus } from 'lucide-react-native';
import { useDraftStore } from '@/store/useDraftStore';
import { useAuthStore } from '@/store/useAuthStore';

const CreateButton = () => {
  const clearCurrentDraft = useDraftStore(state => state.clearCurrentDraft);
  const router = useRouter();
  const scaleAnim = useRef(new Animated.Value(1)).current;

  const handlePressIn = () => {
    Animated.spring(scaleAnim, {
      toValue: 0.9,
      useNativeDriver: true,
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scaleAnim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
    router.push('/new-request/create');
  };

  return (
    <TouchableOpacity
      activeOpacity={0.9}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      style={styles.createButtonContainer}
    >
      <Animated.View style={[styles.createButton, { transform: [{ scale: scaleAnim }] }]}>
        <Plus color={theme.colors.surface} size={28} strokeWidth={2.5} />
      </Animated.View>
    </TouchableOpacity>
  );
};

export default function TabLayout() {
  const router = useRouter();
  const isAuthenticated = useAuthStore(state => state.isAuthenticated);

  useEffect(() => {
    if (!isAuthenticated) {
      router.replace('/(auth)/login');
    }
  }, [isAuthenticated]);

  return (
    <Tabs
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: theme.colors.primary,
        tabBarInactiveTintColor: theme.colors.textTertiary,
        tabBarStyle: {
          backgroundColor: theme.colors.surface,
          borderTopWidth: 0.5,
          borderTopColor: theme.colors.border,
          height: Platform.OS === 'ios' ? 85 : 60,
          paddingBottom: Platform.OS === 'ios' ? 25 : 8,
          paddingTop: 6,
          paddingHorizontal: theme.layout.screenPadding,
          elevation: 8,
          shadowColor: '#000',
          shadowOffset: { width: 0, height: -2 },
          shadowOpacity: 0.06,
          shadowRadius: 6,
        },
        tabBarItemStyle: {
          paddingVertical: 0,
          marginVertical: 0,
        },
        tabBarLabelStyle: {
          fontSize: 11,
          fontWeight: '600',
          marginTop: 4,
        },
      }}>
      
      <Tabs.Screen
        name="home"
        options={{
          title: 'Home',
          tabBarIcon: ({ color }) => <Home size={24} color={color} />,
        }}
      />
      
      <Tabs.Screen
        name="bookings"
        options={{
