        <AppText variant="h4" weight="bold" style={styles.headerTitle}>Order Details</AppText>
        <View style={{ width: 40 }} />
      </View>

      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scrollContent}>
        
        {/* Status Alert */}
        <View style={styles.statusAlert}>
