import React from 'react';
import { View, StyleSheet, ViewStyle, Pressable, PressableProps } from 'react-native';
import { Colors, Radius, Spacing } from '@/constants/theme';
import { AppText } from '@/components/AppText';

interface ChipProps extends Omit<PressableProps, 'children'> {
  label: string;
  selected?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  style?: ViewStyle;
  size?: 'sm' | 'md';
  color?: string;
}

export const Chip = React.memo(function Chip({
  label,
  selected = false,
  leftIcon,
  rightIcon,
  style,
  size = 'md',
  color = Colors.cta,
  ...props
}: ChipProps) {
  const fontSize = size === 'sm' ? 12 : 14;
  const paddingH = size === 'sm' ? Spacing['3'] : Spacing['4'];

  return (
    <Pressable
      style={({ pressed }) => [
        styles.chip,
        {
          paddingHorizontal: paddingH,
          paddingVertical: size === 'sm' ? 6 : 9,
          backgroundColor: selected ? color : Colors.white,
          borderWidth: 1.5,
          borderColor: selected ? color : Colors.border,
          opacity: pressed ? 0.7 : 1,
        },
        style,
      ]}
      accessibilityRole="button"
      accessibilityState={{ selected }}
      accessibilityLabel={label}
      {...props}
    >
      {leftIcon}
      <AppText
        variant="caption"
        weight="semiBold"
        color={selected ? Colors.white : Colors.textPrimary}
        style={{
          marginHorizontal: (leftIcon || rightIcon) ? Spacing['1'] : 0,
        }}
      >
        {label}
      </AppText>
      {rightIcon}
    </Pressable>
  );
});

const styles = StyleSheet.create({
  chip: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: Radius.full,
  },
});

import React, { useState } from 'react';
import { View, StyleSheet, Pressable, Alert, ViewStyle, Platform } from 'react-native';
import { Image } from 'expo-image';
// Removed expo-image-picker to fix Expo Go crash
import { Camera, Upload, X, Image as ImageIcon } from 'lucide-react-native';
import { Colors, Radius, Spacing } from '@/constants/theme';
import { AppText } from './AppText';

interface ImageUploadCardProps {
  label: string;
  description?: string;
  onImageSelected: (uri: string | null) => void;
  error?: string;
  containerStyle?: ViewStyle;
}

export const ImageUploadCard: React.FC<ImageUploadCardProps> = ({
  label,
  description = 'Supports JPG, PNG, HEIC up to 10MB',
  onImageSelected,
  error,
  containerStyle,
}) => {
  const [imageUri, setImageUri] = useState<string | null>(null);

  const handleUploadGallery = async () => {
    // Mock image selection to avoid Expo Go native module errors
    const mockImageUri = 'https://images.pexels.com/photos/3861969/pexels-photo-3861969.jpeg?auto=compress&cs=tinysrgb&w=800';
    setImageUri(mockImageUri);
    onImageSelected(mockImageUri);
  };

  const handleRemove = () => {
    setImageUri(null);
    onImageSelected(null);
  };

  return (
    <View style={[styles.container, containerStyle]}>
      <AppText variant="label" weight="medium" style={styles.label}>
        {label}
      </AppText>

      {imageUri ? (
        <View style={styles.previewContainer}>
          <Image source={{ uri: imageUri }} style={styles.imagePreview} />
          <Pressable style={styles.removeButton} onPress={handleRemove}>
            <X size={20} color={Colors.white} />
          </Pressable>
        </View>
      ) : (
        <View
          style={[
            styles.uploadArea,
            { borderColor: error ? Colors.error : Colors.border },
          ]}
        >
          <View style={styles.iconRow}>
            <Pressable style={styles.actionButton} onPress={handleUploadGallery}>
              <View style={styles.iconCircle}>
                <Upload size={24} color={Colors.primary} />
              </View>
              <AppText variant="bodySm" weight="semiBold" style={styles.actionText}>
                Upload from Gallery
              </AppText>
            </Pressable>
          </View>

          <AppText variant="caption" color={Colors.textTertiary} style={styles.description}>
            {description}
          </AppText>
        </View>
      )}

      {error && (
        <AppText variant="caption" color={Colors.error} style={styles.errorText}>
          {error}
        </AppText>
      )}
    </View>
  );
};

